-- Safe worksheet content import for production.
-- Generated from localhost on 2026-07-12T09:01:55+02:00
-- Import after 2026_07_12_safe_worksheet_schema.sql.
-- Does not modify users/students/payments/orders/subscriptions.
SET @worksheet_foundation_level_id := NULL;
SET @worksheet_level1_id := NULL;
SELECT @worksheet_foundation_level_id := l.id FROM levels l LEFT JOIN courses c ON c.id = l.course_id WHERE (c.slug = 'abacus-worksheet' OR LOWER(c.name) LIKE '%abacus%worksheet%') AND (LOWER(l.level_name) LIKE '%foundation%' OR LOWER(l.level_name) LIKE '%level 0%') ORDER BY l.created_at ASC LIMIT 1;
SELECT @worksheet_level1_id := l.id FROM levels l LEFT JOIN courses c ON c.id = l.course_id WHERE (c.slug = 'abacus-worksheet' OR LOWER(c.name) LIKE '%abacus%worksheet%') AND LOWER(l.level_name) LIKE '%level 1%' ORDER BY l.created_at ASC LIMIT 1;

-- FOUNDATION content. Local level: b6f13d2b-990f-49cf-b7e0-e9fe8761d434 / Abacus Worksheet Level 0 (Foundation)

-- LEVEL1 content. Local level: b3bcf318-5d7e-47a3-a0b7-06ec020a64ba / Abacus Worksheet Level 1

-- Expected imported row counts from localhost source:
-- foundation: topics=14, papers=10, questions=699, options=2400
-- level1: topics=60, papers=60, questions=3600, options=14400

UPDATE worksheet_topics t SET total_questions = (SELECT COUNT(*) FROM worksheet_questions q WHERE q.topic_id = t.id) WHERE t.level_id IN (@worksheet_foundation_level_id, @worksheet_level1_id);
